#include "cg_catalog.hpp"
#include "scene_images.hpp"
#include <iostream>
int main(int argc,char**argv){try{if(argc<2||argc>4)return 2;qlie::Assets assets(argv[1]);whj2::Progress old;if(argc>=3){old.restore(qlie::file(argv[2]));auto upgraded=old.save();whj2::Progress restored;restored.restore(upgraded);if(restored.save()!=upgraded||restored.extras()!=old.extras())throw std::runtime_error("Legacy progress migration mismatch");std::cout<<"PASS legacy progress migration\n";}whj2::CgCatalog catalog(assets);if(catalog.items().size()!=33)throw std::runtime_error("CG group count");whj2::Progress progress;for(size_t i=0;i<33;i++)if(catalog.unlocked(i,progress))throw std::runtime_error("Fresh CG unlocked");
 auto path=catalog.items()[0].files[0];whj2::SceneImages scene(assets);scene.command("^bg1,file:"+path.substr(6)+",show:false");qlie::Bytes pixels(1280*720*4);scene.draw(pixels);if(!scene.takeShownFiles().empty())throw std::runtime_error("Hidden CG recorded");
 scene.command("^bg1,show:true,alpha:0");scene.draw(pixels);if(!scene.takeShownFiles().empty())throw std::runtime_error("Zero alpha CG recorded");scene.command("^bg1,alpha:255");scene.draw(pixels);auto files=scene.takeShownFiles();if(!files.count(path))throw std::runtime_error("Shown CG not recorded");progress.captureFiles(files);if(argc==4){old.captureFiles(files);qlie::write_file(argv[3],old.save());}if(!catalog.unlocked(0,progress)||catalog.unlocked(1,progress))throw std::runtime_error("Group unlock mismatch");
 whj2::Progress restored;restored.restore(progress.save());if(!catalog.unlocked(0,restored)||catalog.unlocked(1,restored))throw std::runtime_error("Seen file persistence");unsigned count=0;for(auto&e:catalog.items())count+=e.files.size();std::cout<<"PASS groups=33 resolved variants="<<count<<" hidden/zero-alpha excluded; shown file unlock and persistence\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<"\n";return 1;}}
